<?php use App\Helpers\ViewHelper; $metrics = $metrics ?? ['revenue'=>0,'orders'=>0,'daily'=>[],'monthly'=>[],'topBooks'=>[],'recentOrders'=>[]]; ?><div class="section-heading"><div><p class="eyebrow">Kinh doanh</p><h2>Dashboard doanh thu</h2></div><span class="muted">Đơn đã hủy không được tính doanh thu</span></div><div class="stats-grid"><div class="stat-card stat-card-highlight"><span>Doanh thu thực ghi nhận</span><strong><?= ViewHelper::money((int)$metrics['revenue']) ?></strong></div><div class="stat-card"><span>Đơn có doanh thu</span><strong><?= (int)$metrics['orders'] ?></strong></div><div class="stat-card"><span>Sách</span><strong><?= (int)($bookCount ?? 0) ?></strong></div><div class="stat-card"><span>Khách hàng</span><strong><?= (int)($customerCount ?? 0) ?></strong></div></div><div class="dashboard-grid"><section class="admin-panel"><div class="section-heading"><div><p class="eyebrow">30 ngày gần nhất</p><h3>Doanh thu theo ngày</h3></div></div><?php if (empty($metrics['daily'])): ?><p class="muted">Chưa có dữ liệu doanh thu.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Ngày</th><th>Đơn</th><th>Doanh thu</th></tr></thead><tbody><?php foreach ($metrics['daily'] as $row): ?><tr><td><?= ViewHelper::escape($row['period']) ?></td><td><?= (int)$row['orders'] ?></td><td><?= ViewHelper::money((int)$row['revenue']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><section class="admin-panel"><div class="section-heading"><div><p class="eyebrow">12 tháng gần nhất</p><h3>Doanh thu theo tháng</h3></div></div><?php if (empty($metrics['monthly'])): ?><p class="muted">Chưa có dữ liệu doanh thu.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Tháng</th><th>Đơn</th><th>Doanh thu</th></tr></thead><tbody><?php foreach ($metrics['monthly'] as $row): ?><tr><td><?= ViewHelper::escape($row['period']) ?></td><td><?= (int)$row['orders'] ?></td><td><?= ViewHelper::money((int)$row['revenue']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div><div class="dashboard-grid"><section class="admin-panel"><div class="section-heading"><div><p class="eyebrow">Sản phẩm</p><h3>Sách bán chạy</h3></div></div><?php if (empty($metrics['topBooks'])): ?><p class="muted">Chưa có dữ liệu bán sách.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Sách</th><th>Số lượng</th><th>Doanh thu</th></tr></thead><tbody><?php foreach ($metrics['topBooks'] as $row): ?><tr><td><?= ViewHelper::escape($row['book_title']) ?></td><td><?= (int)$row['quantity'] ?></td><td><?= ViewHelper::money((int)$row['revenue']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><section class="admin-panel"><div class="section-heading"><div><p class="eyebrow">Vận hành</p><h3>Đơn hàng gần đây</h3></div><a href="/admin/orders">Xem tất cả</a></div><?php if (empty($metrics['recentOrders'])): ?><p class="muted">Chưa có đơn hàng.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Tổng</th><th>Trạng thái</th></tr></thead><tbody><?php foreach ($metrics['recentOrders'] as $row): ?><tr><td><?= ViewHelper::escape($row['order_code']) ?></td><td><?= ViewHelper::escape($row['customer_name']) ?></td><td><?= ViewHelper::money((int)$row['total']) ?></td><td><?= ViewHelper::escape($row['status']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
